import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.mRCPFc5l.js";const _=JSON.parse('{"title":"持续集成与发布","description":"将检查、构建和发布编排为可重复流程，让每次交付都有相同的质量门槛与可回溯产物。","frontmatter":{"title":"持续集成与发布","description":"将检查、构建和发布编排为可重复流程，让每次交付都有相同的质量门槛与可回溯产物。"},"headers":[],"relativePath":"engineering/ci-delivery.md","filePath":"engineering/ci-delivery.md","lastUpdated":1786262003000}'),i={name:"engineering/ci-delivery.md"};function l(r,a,d,p,o,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="持续集成与发布" tabindex="-1">持续集成与发布 <a class="header-anchor" href="#持续集成与发布" aria-label="Permalink to &quot;持续集成与发布&quot;">​</a></h1><p>持续集成不是“自动跑一条命令”，而是把团队已经认可的质量门槛放到每次变更上。任何人提交同一份代码，都应得到同样的检查和同样的构建产物。</p><h2 id="一条最小交付流水线" tabindex="-1">一条最小交付流水线 <a class="header-anchor" href="#一条最小交付流水线" aria-label="Permalink to &quot;一条最小交付流水线&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检出固定版本</span></span>
<span class="line"><span>  → 安装锁定依赖</span></span>
<span class="line"><span>  → 静态检查与测试</span></span>
<span class="line"><span>  → 构建产物</span></span>
<span class="line"><span>  → 部署到目标环境</span></span>
<span class="line"><span>  → 健康检查与记录版本</span></span></code></pre></div><p>每一步都应有明确失败信号。不要把本地手工步骤隐藏在“发布前请记得做”的口头约定里。</p><h2 id="环境差异通过配置表达" tabindex="-1">环境差异通过配置表达 <a class="header-anchor" href="#环境差异通过配置表达" aria-label="Permalink to &quot;环境差异通过配置表达&quot;">​</a></h2><p>代码保持一致，开发、测试和生产的地址、密钥、开关等通过环境配置注入。构建日志不能打印令牌、数据库连接串或个人数据。</p><table tabindex="0"><thead><tr><th>内容</th><th>应放在哪里</th></tr></thead><tbody><tr><td>业务逻辑、默认非敏感值</td><td>代码仓库</td></tr><tr><td>环境地址、功能开关</td><td>受控环境配置</td></tr><tr><td>密钥、证书、令牌</td><td>专用密钥管理或平台机密</td></tr><tr><td>构建产物版本</td><td>发布记录与制品库</td></tr></tbody></table><h2 id="发布要能观察也能回退" tabindex="-1">发布要能观察也能回退 <a class="header-anchor" href="#发布要能观察也能回退" aria-label="Permalink to &quot;发布要能观察也能回退&quot;">​</a></h2><p>发布完成不是流程终点。记录代码版本、配置版本和发布时间；健康检查失败时停止扩散；发现严重问题时，能快速回退到已验证的上一个版本。</p><ul><li>先在接近真实的环境验证，再扩大范围。</li><li>数据库变更采用向前兼容策略，避免代码与表结构无法同时工作。</li><li>为高风险变更加功能开关或灰度路径。</li><li>发布后观察错误、延迟和关键业务指标，而不是只看任务“成功”。</li></ul><p>可重复交付让速度来自确定性，而不是来自某位同事记得更多手工步骤。</p>`,12)])])}const u=t(i,[["render",l]]);export{_ as __pageData,u as default};
